#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <openssl/evp.h>

static double now() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec / 1e9;
}

int main() {
    size_t n = 60000UL * 1024;
    unsigned char *pt = malloc(n);
    unsigned char *out = malloc(n + 32);
    unsigned char key[16], iv[12], aad[32], tag[16];
    memset(pt, 0x5a, n);
    memset(key, 1, 16);
    memset(iv, 2, 12);
    memset(aad, 3, 32);

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    int outlen, total;

    /* warmup */
    for (int i = 0; i < 2; i++) {
        EVP_EncryptInit_ex(ctx, EVP_aes_128_gcm(), NULL, NULL, NULL);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);
        EVP_EncryptInit_ex(ctx, NULL, NULL, key, iv);
        EVP_EncryptUpdate(ctx, NULL, &outlen, aad, 32);
        EVP_EncryptUpdate(ctx, out, &outlen, pt, (int)n);
        total = outlen;
        EVP_EncryptFinal_ex(ctx, out + total, &outlen);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag);
    }

    double t0 = now();
    int reps = 5;
    for (int i = 0; i < reps; i++) {
        EVP_EncryptInit_ex(ctx, EVP_aes_128_gcm(), NULL, NULL, NULL);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);
        EVP_EncryptInit_ex(ctx, NULL, NULL, key, iv);
        EVP_EncryptUpdate(ctx, NULL, &outlen, aad, 32);
        EVP_EncryptUpdate(ctx, out, &outlen, pt, (int)n);
        total = outlen;
        EVP_EncryptFinal_ex(ctx, out + total, &outlen);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag);
    }
    double t1 = now();
    printf("reuse ctx: %.1f ms, %.1f MB/s\n", (t1-t0)/reps*1000, (n/1e6)/((t1-t0)/reps));

    /* new ctx each time */
    t0 = now();
    for (int i = 0; i < reps; i++) {
        EVP_CIPHER_CTX *c = EVP_CIPHER_CTX_new();
        EVP_EncryptInit_ex(c, EVP_aes_128_gcm(), NULL, NULL, NULL);
        EVP_CIPHER_CTX_ctrl(c, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);
        EVP_EncryptInit_ex(c, NULL, NULL, key, iv);
        EVP_EncryptUpdate(c, NULL, &outlen, aad, 32);
        EVP_EncryptUpdate(c, out, &outlen, pt, (int)n);
        total = outlen;
        EVP_EncryptFinal_ex(c, out + total, &outlen);
        EVP_CIPHER_CTX_ctrl(c, EVP_CTRL_GCM_GET_TAG, 16, tag);
        EVP_CIPHER_CTX_free(c);
    }
    t1 = now();
    printf("new ctx: %.1f ms, %.1f MB/s\n", (t1-t0)/reps*1000, (n/1e6)/((t1-t0)/reps));

    /* EVP_Cipher one-shot style: init once fully then reset via Init with NULL cipher */
    t0 = now();
    for (int i = 0; i < reps; i++) {
        EVP_EncryptInit_ex(ctx, NULL, NULL, key, iv);
        EVP_EncryptUpdate(ctx, NULL, &outlen, aad, 32);
        EVP_EncryptUpdate(ctx, out, &outlen, pt, (int)n);
        total = outlen;
        EVP_EncryptFinal_ex(ctx, out + total, &outlen);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag);
    }
    t1 = now();
    printf("reinit key/iv only: %.1f ms, %.1f MB/s\n", (t1-t0)/reps*1000, (n/1e6)/((t1-t0)/reps));

    printf("tag0=%02x\n", tag[0]);
    return 0;
}
EOF
