cat > bench_pth.c << 'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <openssl/evp.h>

static double now() { struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts); return ts.tv_sec + ts.tv_nsec/1e9; }

typedef struct { unsigned char *pt, *out; size_t off, len; unsigned char *key; int klen; unsigned char *iv; unsigned char *aad; int aadlen; unsigned char tag[16]; } Job;

void *worker(void *arg) {
    Job *j = arg;
    EVP_CIPHER_CTX *c = EVP_CIPHER_CTX_new();
    int outlen;
    const EVP_CIPHER *cipher = j->klen==16 ? EVP_aes_128_gcm() : j->klen==24 ? EVP_aes_192_gcm() : EVP_aes_256_gcm();
    EVP_EncryptInit_ex(c, cipher, NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(c, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);
    EVP_EncryptInit_ex(c, NULL, NULL, j->key, j->iv);
    if (j->aadlen) EVP_EncryptUpdate(c, NULL, &outlen, j->aad, j->aadlen);
    EVP_EncryptUpdate(c, j->out + j->off, &outlen, j->pt + j->off, (int)j->len);
    EVP_EncryptFinal_ex(c, j->out + j->off + outlen, &outlen);
    EVP_CIPHER_CTX_ctrl(c, EVP_CTRL_GCM_GET_TAG, 16, j->tag);
    EVP_CIPHER_CTX_free(c);
    return NULL;
}

void run(int T, size_t n, unsigned char *pt, unsigned char *out, unsigned char *key) {
    unsigned char iv[12]; memset(iv, 2, 12);
    unsigned char aad[32]; memset(aad, 3, 32);
    pthread_t th[16];
    Job jobs[16];
    size_t chunk = n / T;
    for (int t = 0; t < T; t++) {
        jobs[t].pt = pt; jobs[t].out = out;
        jobs[t].off = t * chunk;
        jobs[t].len = (t == T-1) ? n - t*chunk : chunk;
        jobs[t].key = key; jobs[t].klen = 16;
        jobs[t].iv = iv; jobs[t].aad = aad; jobs[t].aadlen = 32;
        pthread_create(&th[t], NULL, worker, &jobs[t]);
    }
    for (int t = 0; t < T; t++) pthread_join(th[t], NULL);
}

int main() {
    size_t n = 60000UL * 1024;
    unsigned char *pt = malloc(n), *out = malloc(n+64);
    memset(pt, 0x5a, n);
    unsigned char key[16]; memset(key, 1, 16);
    int Ts[] = {1,2,3,4,6,8};
    for (int i = 0; i < 6; i++) {
        int T = Ts[i];
        run(T, n, pt, out, key);
        double t0 = now();
        int reps = 4;
        for (int r = 0; r < reps; r++) run(T, n, pt, out, key);
        double t1 = now();
        printf("threads=%d: %.2f ms, %.0f MB/s\n", T, (t1-t0)/reps*1000, (n/1e6)/((t1-t0)/reps));
    }
    return 0;
}
EOF
