{"command":"export TMPDIR="$HOME/tmp"
cat > bench_ghash.c << 'EOF'
#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <immintrin.h>

static double now() { struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts); return ts.tv_sec + ts.tv_nsec/1e9; }

/* pclmul schoolbook multiply */
static inline __m128i clmul_lo(__m128i a, __m128i b) { return _mm_clmulepi64_si128(a, b, 0x00); }
static inline __m128i clmul_hi(__m128i a, __m128i b) { return _mm_clmulepi64_si128(a, b, 0x11); }
static inline __m128i clmul_m1(__m128i a, __m128i b) { return _mm_clmulepi64_si128(a, b, 0x10); }
static inline __m128i clmul_m2(__m128i a, __m128i b) { return _mm_clmulepi64_si128(a, b, 0x01); }

/* reduction of 256-bit product (lo, mid, hi) modulo gcm polynomial. 
   Standard Intel approach: reflect? We'll do the bit-reflected GHASH reduction
   used by Intel's ghash (polynomial x^128+x^7+x^2+x+1 reflected = 0xe1...00). */
static inline __m128i ghash_reduce(__m128i X0, __m128i X1) {
    /* X0 = low 128, X1 = high 128 of product */
    __m128i poly = _mm_set_epi64x(0, 0xe100000000000000ULL);
    __m128i t = _mm_clmulepi64_si128(X0, poly, 0x00);
    __m128i a = _mm_xor_si128(_mm_shuffle_epi32(X0, 78), t); /* swap halves xor t? */
    /* Actually use the well-known 2-step reduction:
       T = X0
       X0 = clmul(T, poly) xor (T >> 64) ... let me use the canonical form below. */
    return X0; /* placeholder replaced below */
}

/* Canonical Intel reduction (from Intel GHASH whitepaper), bit-reflected form:
   Input: GH = high 128 bits, GL = low 128 bits of the 256-bit product.
   poly = 0x1 | (0xc2 << 120)  i.e. _mm_setr_epi32(0,0,0,0xc2000000) ? 
   We'll test both against a reference later. For the benchmark we just want throughput. */
static inline __m128i reduce(__m128i lo, __m128i hi) {
    __m128i p = _mm_set_epi32(0, 0, 0, 0xc2000000);
    __m128i t1 = _mm_clmulepi64_si128(lo, p, 0x00);
    __m128i t2 = _mm_shuffle_epi32(lo, 78); /* swap 64-bit halves */
    __m128i t3 = _mm_xor_si128(t2, t1);
    __m128i t4 = _mm_clmulepi64_si128(t3, p, 0x00); /* not quite */
    (void)t4; (void)hi;
    return lo;
}

int main() {
    size_t n = 60000UL * 1024;
    unsigned char *buf = aligned_alloc(64, n);
    memset(buf, 0x5a, n);
    __m128i H = _mm_set_epi64x(0x1234567890abcdefULL, 0xfedcba0987654321ULL);
    __m128i acc = _mm_setzero_si128();

    /* 1 block per iteration */
    double t0 = now();
    int reps = 3;
    for (int r = 0; r < reps; r++) {
        __m128i a = acc;
        for (size_t i = 0; i < n; i += 16) {
            __m128i x = _mm_loadu_si128((const __m128i*)(buf + i));
            x = _mm_xor_si128(x, a);
            __m128i lo = _mm_clmulepi64_si128(x, H, 0x00);
            __m128i hi = _mm_clmulepi64_si128(x, H, 0x11);
            __m128i m1 = _mm_clmulepi64_si128(x, H, 0x10);
            __m128i m2 = _mm_clmulepi64_si128(x, H, 0x01);
            __m128i mid = _mm_xor_si128(m1, m2);
            lo = _mm_xor_si128(lo, _mm_slli_si128(mid, 8));
            hi = _mm_xor_si128(hi, _mm_srli_si128(mid, 8));
            /* reduction */
            __m128i p = _mm_set_epi32(0xc2000000, 0, 0, 0);
            __m128i t = _mm_clmulepi64_si128(lo, p, 0x01);
            lo = _mm_xor_si128(lo, _mm_slli_si128(t, 8));
            hi = _mm_xor_si128(hi, _mm_srli_si128(t, 8));
            t = _mm_clmulepi64_si128(lo, p, 0x00);
            a = _mm_xor_si128(hi, t);
        }
        acc = a;
    }
    double t1 = now();
    printf("ghash 1-way: %.1f ms, %.0f MB/s\n", (t1-t0)/reps*1000, (n/1e6)/((t1-t0)/reps));

    /* 8-way aggregated GHASH: 8 independent multiplies per iteration (simulates 8-block aggregation) */
    t0 = now();
    for (int r = 0; r < reps; r++) {
        __m128i a = acc;
        __m128i Hpow[8];
        for (int k = 0; k < 8; k++) Hpow[k] = H;
        for (size_t i = 0; i + 128 <= n; i += 128) {
            __m128i lo = _mm_setzero_si128(), hi = _mm_setzero_si128(), mid = _mm_setzero_si128();
            for (int k = 0; k < 8; k++) {
                __m128i x = _mm_loadu_si128((const __m128i*)(buf + i + k*16));
                lo = _mm_xor_si128(lo, _mm_clmulepi64_si128(x, Hpow[k], 0x00));
                hi = _mm_xor_si128(hi, _mm_clmulepi64_si128(x, Hpow[k], 0x11));
                mid = _mm_xor_si128(mid, _mm_clmulepi64_si128(x, Hpow[k], 0x10));
                mid = _mm_xor_si128(mid, _mm_clmulepi64_si128(x, Hpow[k], 0x01));
            }
            lo = _mm_xor_si128(lo, _mm_slli_si128(mid, 8));
            hi = _mm_xor_si128(hi, _mm_srli_si128(mid, 8));
            __m128i p = _mm_set_epi32(0xc2000000, 0, 0, 0);
            __m128i t = _mm_clmulepi64_si128(lo, p, 0x01);
            lo = _mm_xor_si128(lo, _mm_slli_si128(t, 8));
            hi = _mm_xor_si128(hi, _mm_srli_si128(t, 8));
            t = _mm_clmulepi64_si128(lo, p, 0x00);
            a = _mm_xor_si128(hi, t);
            (void)a;
        }
        acc = a;
    }
    t1 = now();
    printf("ghash 8-way agg: %.1f ms, %.0f MB/s\n", (t1-t0)/reps*1000, (n/1e6)/((t1-t0)/reps));

    /* AES-NI throughput: 8 blocks pipelined */
    __m128i rk[11];
    for (int k = 0; k < 11; k++) rk[k] = _mm_set_epi64x(k, k*3);
    t0 = now();
    for (int r = 0; r < reps; r++) {
        for (size_t i = 0; i + 128 <= n; i += 128) {
            __m128i b0 = _mm_loadu_si128((const __m128i*)(buf+i));
            __m128i b1 = _mm_loadu_si128((const __m128i*)(buf+i+16));
            __m128i b2 = _mm_loadu_si128((const __m128i*)(buf+i+32));
            __m128i b3 = _mm_loadu_si128((const __m128i*)(buf+i+48));
            __m128i b4 = _mm_loadu_si128((const __m128i*)(buf+i+64));
            __m128i b5 = _mm_loadu_si128((const __m128i*)(buf+i+80));
            __m128i b6 = _mm_loadu_si128((const __m128i*)(buf+i+96));
            __m128i b7 = _mm_loadu_si128((const __m128i*)(buf+i+112));
            b0 = _mm_xor_si128(b0, rk[0]); b1 = _mm_xor_si128(b1, rk[0]);
            b2 = _mm_xor_si128(b2, rk[0]); b3 = _mm_xor_si128(b3, rk[0]);
            b4 = _mm_xor_si128(b4, rk[0]); b5 = _mm_xor_si128(b5, rk[0]);
            b6 = _mm_xor_si128(b6, rk[0]); b7 = _mm_xor_si128(b7, rk[0]);
            for (int rnd = 1; rnd < 10; rnd++) {
                b0 = _mm_aesenc_si128(b0, rk[rnd]); b1 = _mm_aesenc_si128(b1, rk[rnd]);
                b2 = _mm_aesenc_si128(b2, rk[rnd]); b3 = _mm_aesenc_si128(b3, rk[rnd]);
                b4 = _mm_aesenc_si128(b4, rk[rnd]); b5 = _mm_aesenc_si128(b5, rk[rnd]);
                b6 = _mm_aesenc_si128(b6, rk[rnd]); b7 = _mm_aesenc_si128(b7, rk[rnd]);
            }
            b0 = _mm_aesenclast_si128(b0, rk[10]); b1 = _mm_aesenclast_si128(b1, rk[10]);
            b2 = _mm_aesenclast_si128(b2, rk[10]); b3 = _mm_aesenclast_si128(b3, rk[10]);
            b4 = _mm_aesenclast_si128(b4, rk[10]); b5 = _mm_aesenclast_si128(b5, rk[10]);
            b6 = _mm_aesenclast_si128(b6, rk[10]); b7 = _mm_aesenclast_si128(b7, rk[10]);
            _mm_storeu_si128((__m128i*)(buf+i), b0);
            _mm_storeu_si128((__m128i*)(buf+i+16), b1);
            _mm_storeu_si128((__m128i*)(buf+i+32), b2);
            _mm_storeu_si128((__m128i*)(buf+i+48), b3);
            _mm_storeu_si128((__m128i*)(buf+i+64), b4);
            _mm_storeu_si128((__m128i*)(buf+i+80), b5);
            _mm_storeu_si128((__m128i*)(buf+i+96), b6);
            _mm_storeu_si128((__m128i*)(buf+i+112), b7);
        }
    }
    t1 = now();
    printf("aes-128 8-block: %.1f ms, %.0f MB/s\n", (t1-t0)/reps*1000, (n/1e6)/((t1-t0)/reps));
    printf("acc=%llx\n", (unsigned long long)_mm_cvtsi128_si64(acc));
    return 0;
}
EOF
