        __m128i a = _mm_setzero_si128();
        for (size_t i = 0; i < n; i += 16) {
            __m128i x = _mm_xor_si128(_mm_loadu_si128((const __m128i*)(buf + i)), a);
            __m128i lo = _mm_clmulepi64_si128(x, H, 0x00);
