            __m128i b4=ctr; ctr=_mm_add_epi64(ctr, _mm_set_epi64x(0,1));
            __m128i b5=ctr; ctr=_mm_add_epi64(ctr, _mm_set_epi64x(0,1));
            __m128i b6=ctr; ctr=_mm_add_epi64(ctr, _mm_set_epi64x(0,1));
            __m128i b7=ctr; ctr=_mm_add_epi64(ctr, _mm_set_epi64x(0,1));
            b0=_mm_xor_si128(b0,rk[0]); b1=_mm_xor_si128(b1,rk[0]); b2=_mm_xor_si128(b2,rk[0]); b3=_mm_xor_si128(b3,rk[0]);
            b4=_mm_xor_si128(b4,rk[0]); b5=_mm_xor_si128(b5,rk[0]); b6=_mm_xor_si128(b6,rk[0]); b7=_mm_xor_si128(b7,rk[0]);
            for (int rnd=1; rnd<10; rnd++) {
                b0=_mm_aesenc_si128(b0,rk[rnd]); b1=_mm_aesenc_si128(b1,rk[rnd]);
                b2=_mm_aesenc_si128(b2,rk[rnd]); b3=_mm_aesenc_si128(b3,rk[rnd]);
                b4=_mm_aesenc_si128(b4,rk[rnd]); b5=_mm_aesenc_si128(b5,rk[rnd]);
                b6=_mm_aesenc_si128(b6,rk[rnd]); b7=_mm_aesenc_si128(b7,rk[rnd]);
