            _mm_storeu_si128((__m128i*)(out+i+112), _mm_xor_si128(b7, _mm_loadu_si128((const __m128i*)(buf+i+112))));
        }
    }
    t1 = now();
    sink = out[0];
    printf("aes-128-ctr 8blk: %.1f ms, %.0f MB/s\n", (t1-t0)/reps*1000.0, (n/1e6)/((t1-t0)/reps));
    return 0;
}
