static volatile uint64_t sink;

typedef struct { unsigned char *buf, *out; size_t off, len; __m128i rk[11]; } Job;

void *worker(void *arg) {
    Job *j = arg;
    __m128i *rk = j->rk;
    __m128i one = _mm_set_epi64x(0, 1);
    __m128i ctr = _mm_set_epi64x(0, (long long)(j->off/16));
