#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <immintrin.h>

static double now() { struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts); return ts.tv_sec + ts.tv_nsec/1e9; }

#define MAX_T 16
typedef struct {
    pthread_t th;
    int id, T;
    pthread_mutex_t mtx;
    pthread_cond_t cv, done_cv;
    int job;      /* 0 idle, 1 work, -1 exit */
    int done;
    unsigned char *buf, *out;
    size_t n;
    __m128i rk[15];
    int nrounds;
} Worker;

static void aes_ctr_chunk(Worker *w) {
    size_t n = w->n;
    size_t chunk = (n / w->T) & ~127UL;
    size_t off = w->id * chunk;
    size_t end = (w->id == w->T - 1) ? n : off + chunk;
    __m128i *rk = w->rk;
    int nr = w->nrounds;
    __m128i one = _mm_set_epi64x(0, 1);
    __m128i ctr = _mm_set_epi64x(0, (long long)(off / 16));
    unsigned char *buf = w->buf, *out = w->out;
    for (size_t i = off; i + 128 <= end; i += 128) {
        __m128i b0=ctr; ctr=_mm_add_epi64(ctr,one);
        __m128i b1=ctr; ctr=_mm_add_epi64(ctr,one);
        __m128i b2=ctr; ctr=_mm_add_epi64(ctr,one);
        __m128i b3=ctr; ctr=_mm_add_epi64(ctr,one);
        __m128i b4=ctr; ctr=_mm_add_epi64(ctr,one);
        __m128i b5=ctr; ctr=_mm_add_epi64(ctr,one);
        __m128i b6=ctr; ctr=_mm_add_epi64(ctr,one);
        __m128i b7=ctr; ctr=_mm_add_epi64(ctr,one);
        b0=_mm_xor_si128(b0,rk[0]); b1=_mm_xor_si128(b1,rk[0]); b2=_mm_xor_si128(b2,rk[0]); b3=_mm_xor_si128(b3,rk[0]);
        b4=_mm_xor_si128(b4,rk[0]); b5=_mm_xor_si128(b5,rk[0]); b6=_mm_xor_si128(b6,rk[0]); b7=_mm_xor_si128(b7,rk[0]);
        for (int rnd=1; rnd<nr; rnd++) {
            b0=_mm_aesenc_si128(b0,rk[rnd]); b1=_mm_aesenc_si128(b1,rk[rnd]);
            b2=_mm_aesenc_si128(b2,rk[rnd]); b3=_mm_aesenc_si128(b3,rk[rnd]);
            b4=_mm_aesenc_si128(b4,rk[rnd]); b5=_mm_aesenc_si128(b5,rk[rnd]);
            b6=_mm_aesenc_si128(b6,rk[rnd]); b7=_mm_aesenc_si128(b7,rk[rnd]);
        }
        b0=_mm_aesenclast_si128(b0,rk[nr]); b1=_mm_aesenclast_si128(b1,rk[nr]);
        b2=_mm_aesenclast_si128(b2,rk[nr]); b3=_mm_aesenclast_si128(b3,rk[nr]);
        b4=_mm_aesenclast_si128(b4,rk[nr]); b5=_mm_aesenclast_si128(b5,rk[nr]);
        b6=_mm_aesenclast_si128(b6,rk[nr]); b7=_mm_aesenclast_si128(b7,rk[nr]);
        _mm_storeu_si128((__m128i*)(out+i),    _mm_xor_si128(b0,_mm_loadu_si128((const __m128i*)(buf+i))));
        _mm_storeu_si128((__m128i*)(out+i+16), _mm_xor_si128(b1,_mm_loadu_si128((const __m128i*)(buf+i+16))));
        _mm_storeu_si128((__m128i*)(out+i+32), _mm_xor_si128(b2,_mm_loadu_si128((const __m128i*)(buf+i+32))));
        _mm_storeu_si128((__m128i*)(out+i+48), _mm_xor_si128(b3,_mm_loadu_si128((const __m128i*)(buf+i+48))));
        _mm_storeu_si128((__m128i*)(out+i+64), _mm_xor_si128(b4,_mm_loadu_si128((const __m128i*)(buf+i+64))));
        _mm_storeu_si128((__m128i*)(out+i+80), _mm_xor_si128(b5,_mm_loadu_si128((const __m128i*)(buf+i+80))));
        _mm_storeu_si128((__m128i*)(out+i+96), _mm_xor_si128(b6,_mm_loadu_si128((const __m128i*)(buf+i+96))));
        _mm_storeu_si128((__m128i*)(out+i+112),_mm_xor_si128(b7,_mm_loadu_si128((const __m128i*)(buf+i+112))));
    }
}

void *thread_main(void *arg) {
    Worker *w = arg;
    pthread_mutex_lock(&w->mtx);
    for (;;) {
        while (w->job == 0) pthread_cond_wait(&w->cv, &w->mtx);
        if (w->job < 0) { pthread_mutex_unlock(&w->mtx); return NULL; }
        pthread_mutex_unlock(&w->mtx);
        aes_ctr_chunk(w);
        pthread_mutex_lock(&w->mtx);
        w->job = 0; w->done = 1;
        pthread_cond_signal(&w->done_cv);
    }
}

int main() {
    size_t n = 60000UL * 1024;
    unsigned char *buf = aligned_alloc(64, n), *out = aligned_alloc(64, n);
    memset(buf, 0x5a, n);
    int Ts[] = {1,2,4,6,8,12};
    for (int ti = 0; ti < 6; ti++) {
        int T = Ts[ti];
        Worker ws[MAX_T];
        for (int t = 0; t < T; t++) {
            memset(&ws[t], 0, sizeof(Worker));
            ws[t].id = t; ws[t].T = T; ws[t].n = n; ws[t].buf = buf; ws[t].out = out;
            ws[t].nrounds = 10;
            for (int k = 0; k <= 10; k++) ws[t].rk[k] = _mm_set_epi64x(k*7+1, k*3+5);
            pthread_mutex_init(&ws[t].mtx, NULL);
            pthread_cond_init(&ws[t].cv, NULL);
            pthread_cond_init(&ws[t].done_cv, NULL);
            pthread_create(&ws[t].th, NULL, thread_main, &ws[t]);
        }
        /* warmup */
        for (int t=0;t<T;t++){ pthread_mutex_lock(&ws[t].mtx); ws[t].done=0; ws[t].job=1; pthread_cond_signal(&ws[t].cv); pthread_mutex_unlock(&ws[t].mtx); }
        for (int t=0;t<T;t++){ pthread_mutex_lock(&ws[t].mtx); while(!ws[t].done) pthread_cond_wait(&ws[t].done_cv,&ws[t].mtx); pthread_mutex_unlock(&ws[t].mtx); }
        int reps = 4;
        double t0 = now();
        for (int r = 0; r < reps; r++) {
            for (int t=0;t<T;t++){ pthread_mutex_lock(&ws[t].mtx); ws[t].done=0; ws[t].job=1; pthread_cond_signal(&ws[t].cv); pthread_mutex_unlock(&ws[t].mtx); }
            for (int t=0;t<T;t++){ pthread_mutex_lock(&ws[t].mtx); while(!ws[t].done) pthread_cond_wait(&ws[t].done_cv,&ws[t].mtx); pthread_mutex_unlock(&ws[t].mtx); }
        }
        double t1 = now();
        printf("threads=%d: %.2f ms, %.0f MB/s\n", T, (t1-t0)/reps*1000, (n/1e6)/((t1-t0)/reps));
        for (int t=0;t<T;t++){ pthread_mutex_lock(&ws[t].mtx); ws[t].job=-1; pthread_cond_signal(&ws[t].cv); pthread_mutex_unlock(&ws[t].mtx); pthread_join(ws[t].th, NULL); }
    }
    return 0;
}
