#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <openssl/evp.h>

static double now() { struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts); return ts.tv_sec + ts.tv_nsec/1e9; }

#define MAX_T 16
typedef struct {
    pthread_t th;
    pthread_mutex_t mtx; pthread_cond_t cv, done_cv;
    int job, done, id, T;
    unsigned char *in, *out; size_t n;
    unsigned char key[32]; int klen;
    unsigned char iv[16]; int ivlen;
    unsigned char aad[256]; int aadlen;
    unsigned char tag[16];
    EVP_CIPHER_CTX *ctx;
} Worker;

static void do_work(Worker *w) {
    size_t chunk = (w->n / w->T);
    size_t off = w->id * chunk;
    size_t len = (w->id == w->T-1) ? w->n - off : chunk;
    int outlen;
    EVP_CIPHER_CTX *c = w->ctx;
    const EVP_CIPHER *cipher = w->klen==16 ? EVP_aes_128_gcm() : w->klen==24 ? EVP_aes_192_gcm() : EVP_aes_256_gcm();
    EVP_EncryptInit_ex(c, cipher, NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(c, EVP_CTRL_GCM_SET_IVLEN, w->ivlen, NULL);
    EVP_EncryptInit_ex(c, NULL, NULL, w->key, w->iv);
    if (w->aadlen) EVP_EncryptUpdate(c, NULL, &outlen, w->aad, w->aadlen);
    EVP_EncryptUpdate(c, w->out + off, &outlen, w->in + off, (int)len);
    EVP_EncryptFinal_ex(c, w->out + off + outlen, &outlen);
    EVP_CIPHER_CTX_ctrl(c, EVP_CTRL_GCM_GET_TAG, 16, w->tag);
}

void *thread_main(void *arg) {
    Worker *w = arg;
    w->ctx = EVP_CIPHER_CTX_new();
    pthread_mutex_lock(&w->mtx);
    for (;;) {
        while (w->job == 0) pthread_cond_wait(&w->cv, &w->mtx);
        if (w->job < 0) { pthread_mutex_unlock(&w->mtx); return NULL; }
        pthread_mutex_unlock(&w->mtx);
        do_work(w);
        pthread_mutex_lock(&w->mtx);
        w->job = 0; w->done = 1;
        pthread_cond_signal(&w->done_cv);
    }
}

int main() {
    size_t n = 60000UL * 1024;
    unsigned char *in = malloc(n), *out = malloc(n + 64);
    memset(in, 0x5a, n);
    int Ts[] = {1,2,4,6,8};
    for (int ti = 0; ti < 5; ti++) {
        int T = Ts[ti];
        Worker ws[MAX_T];
        for (int t = 0; t < T; t++) {
            memset(&ws[t], 0, sizeof(Worker));
            ws[t].id=t; ws[t].T=T; ws[t].n=n; ws[t].in=in; ws[t].out=out;
            ws[t].klen=16; memset(ws[t].key,1,16); ws[t].ivlen=12; memset(ws[t].iv,2,12);
            ws[t].aadlen=32; memset(ws[t].aad,3,32);
            pthread_mutex_init(&ws[t].mtx,NULL); pthread_cond_init(&ws[t].cv,NULL); pthread_cond_init(&ws[t].done_cv,NULL);
            pthread_create(&ws[t].th, NULL, thread_main, &ws[t]);
        }
        int reps = 4;
        for (int r = -1; r < reps; r++) {
            double t0 = now();
            for (int t=0;t<T;t++){ pthread_mutex_lock(&ws[t].mtx); ws[t].done=0; ws[t].job=1; pthread_cond_signal(&ws[t].cv); pthread_mutex_unlock(&ws[t].mtx);} 
            for (int t=0;t<T;t++){ pthread_mutex_lock(&ws[t].mtx); while(!ws[t].done) pthread_cond_wait(&ws[t].done_cv,&ws[t].mtx); pthread_mutex_unlock(&ws[t].mtx);} 
            double t1 = now();
            if (r >= 0 && r == reps-1) printf("threads=%d: %.2f ms, %.0f MB/s\n", T, (t1-t0)*1000, (n/1e6)/(t1-t0));
        }
        /* measure average */
        double t0 = now();
        for (int r = 0; r < reps; r++) {
            for (int t=0;t<T;t++){ pthread_mutex_lock(&ws[t].mtx); ws[t].done=0; ws[t].job=1; pthread_cond_signal(&ws[t].cv); pthread_mutex_unlock(&ws[t].mtx);} 
            for (int t=0;t<T;t++){ pthread_mutex_lock(&ws[t].mtx); while(!ws[t].done) pthread_cond_wait(&ws[t].done_cv,&ws[t].mtx); pthread_mutex_unlock(&ws[t].mtx);} 
        }
        double t1 = now();
        printf("  avg threads=%d: %.2f ms, %.0f MB/s\n", T, (t1-t0)/reps*1000, (n/1e6)/((t1-t0)/reps));
        for (int t=0;t<T;t++){ pthread_mutex_lock(&ws[t].mtx); ws[t].job=-1; pthread_cond_signal(&ws[t].cv); pthread_mutex_unlock(&ws[t].mtx); pthread_join(ws[t].th,NULL);} 
    }
    return 0;
}
