static double now(){struct timespec ts;clock_gettime(CLOCK_MONOTONIC,&ts);return ts.tv_sec+ts.tv_nsec/1e9.0;}
static volatile uint64_t sink;

typedef struct { int id,T; unsigned char *in,*out; size_t n; __m128i rk[15]; int nr; __m128i Hp[8]; __m128i acc; int pass; } Job;

static inline __m128i ghash_reduce(__m128i lo,__m128i mid,__m128i hi){
    lo=_mm_xor_si128(lo,_mm_slli_si128(mid,8)); hi=_mm_xor_si128(hi,_mm_srli_si128(mid,8));
    __m128i p=_mm_set_epi32(0xc2000000,0,0,0);
