    lo=_mm_xor_si128(lo,_mm_slli_si128(t,8)); hi=_mm_xor_si128(hi,_mm_srli_si128(t,8));
    t=_mm_clmulepi64_si128(lo,p,0x00); return _mm_xor_si128(hi,t);
}

void *worker(void *arg){
    Job *j=arg;
    size_t chunk=(j->n/j->T)&~127UL;
    size_t off=j->id*chunk;
    size_t end=(j->id==j->T-1)?j->n:off+chunk;
    if(j->pass==1){
        __m128i *rk=j->rk; int nr=j->nr; __m128i one=_mm_set_epi64x(0,1);
        __m128i ctr=_mm_set_epi64x(0,(long long)(off/16));
        for(size_t i=off;i+128<=end;i+=128){
            __m128i c0=ctr;ctr=_mm_add_epi64(ctr,one);
            __m128i c1=ctr;ctr=_mm_add_epi64(ctr,one);
            __m128i c2=ctr;ctr=_mm_add_epi64(ctr,one);
            __m128i c3=ctr;ctr=_mm_add_epi64(ctr,one);
            __m128i c4=ctr;ctr=_mm_add_epi64(ctr,one);
            __m128i c5=ctr;ctr=_mm_add_epi64(ctr,one);
            __m128i c6=ctr;ctr=_mm_add_epi64(ctr,one);
            __m128i c7=ctr;ctr=_mm_add_epi64(ctr,one);
            c0=_mm_xor_si128(c0,rk[0]);c1=_mm_xor_si128(c1,rk[0]);c2=_mm_xor_si128(c2,rk[0]);c3=_mm_xor_si128(c3,rk[0]);
            c4=_mm_xor_si128(c4,rk[0]);c5=_mm_xor_si128(c5,rk[0]);c6=_mm_xor_si128(c6,rk[0]);c7=_mm_xor_si128(c7,rk[0]);
            for(int rnd=1;rnd<nr;rnd++){
                c0=_mm_aesenc_si128(c0,rk[rnd]);c1=_mm_aesenc_si128(c1,rk[rnd]);c2=_mm_aesenc_si128(c2,rk[rnd]);c3=_mm_aesenc_si128(c3,rk[rnd]);
                c4=_mm_aesenc_si128(c4,rk[rnd]);c5=_mm_aesenc_si128(c5,rk[rnd]);c6=_mm_aesenc_si128(c6,rk[rnd]);c7=_mm_aesenc_si128(c7,rk[rnd]);
            }
            c0=_mm_aesenclast_si128(c0,rk[nr]);c1=_mm_aesenclast_si128(c1,rk[nr]);c2=_mm_aesenclast_si128(c2,rk[nr]);c3=_mm_aesenclast_si128(c3,rk[nr]);
            c4=_mm_aesenclast_si128(c4,rk[nr]);c5=_mm_aesenclast_si128(c5,rk[nr]);c6=_mm_aesenclast_si128(c6,rk[nr]);c7=_mm_aesenclast_si128(c7,rk[nr]);
            _mm_storeu_si128((__m128i*)(j->out+i),_mm_xor_si128(c0,_mm_loadu_si128((const __m128i*)(j->in+i))));
            _mm_storeu_si128((__m128i*)(j->out+i+16),_mm_xor_si128(c1,_mm_loadu_si128((const __m128i*)(j->in+i+16))));
            _mm_storeu_si128((__m128i*)(j->out+i+32),_mm_xor_si128(c2,_mm_loadu_si128((const __m128i*)(j->in+i+32))));
            _mm_storeu_si128((__m128i*)(j->out+i+48),_mm_xor_si128(c3,_mm_loadu_si128((const __m128i*)(j->in+i+48))));
            _mm_storeu_si128((__m128i*)(j->out+i+64),_mm_xor_si128(c4,_mm_loadu_si128((const __m128i*)(j->in+i+64))));
            _mm_storeu_si128((__m128i*)(j->out+i+80),_mm_xor_si128(c5,_mm_loadu_si128((const __m128i*)(j->in+i+80))));
            _mm_storeu_si128((__m128i*)(j->out+i+96),_mm_xor_si128(c6,_mm_loadu_si128((const __m128i*)(j->in+i+96))));
            _mm_storeu_si128((__m128i*)(j->out+i+112),_mm_xor_si128(c7,_mm_loadu_si128((const __m128i*)(j->in+i+112))));
        }
    } else {
        __m128i acc=_mm_setzero_si128(); __m128i *Hp=j->Hp;
        for(size_t i=off;i+128<=end;i+=128){
            __m128i x0=_mm_loadu_si128((const __m128i*)(j->out+i));
