            __m128i lo=_mm_clmulepi64_si128(x0,Hp[0],0x00);
            __m128i hi=_mm_clmulepi64_si128(x0,Hp[0],0x11);
            __m128i mid=_mm_xor_si128(_mm_clmulepi64_si128(x0,Hp[0],0x10),_mm_clmulepi64_si128(x0,Hp[0],0x01));
            #define GA(x,k) do{lo=_mm_xor_si128(lo,_mm_clmulepi64_si128(x,Hp[k],0x00));hi=_mm_xor_si128(hi,_mm_clmulepi64_si128(x,Hp[k],0x11));mid=_mm_xor_si128(mid,_mm_xor_si128(_mm_clmulepi64_si128(x,Hp[k],0x10),_mm_clmulepi64_si128(x,Hp[k],0x01)));}while(0)
            GA(x1,1);GA(x2,2);GA(x3,3);GA(x4,4);GA(x5,5);GA(x6,6);GA(x7,7);
            acc=ghash_reduce(lo,mid,hi);
        }
        j->acc=acc;
    }
    return NULL;
}

double bench(int T, int pass, size_t n, unsigned char *in, unsigned char *out){
    pthread_t th[16]; Job jobs[16];
    size_t chunk=(n/T)&~127UL;
    int reps=3; double t0=now();
