/* Build a bytes object directly and streaming-copy src into it (the minimum
   memory traffic any correct encryption must perform: read input, write output). */
static PyObject *copy_floor(PyObject *self, PyObject *args){
    Py_buffer v;
    if(!PyArg_ParseTuple(args,"y*",&v)) return NULL;
    Py_ssize_t n = v.len;
    PyBytesObject *op = (PyBytesObject *)PyObject_Malloc(sizeof(PyBytesObject) + n);
    if(!op){ PyBuffer_Release(&v); return PyErr_NoMemory(); }
    PyObject_INIT_VAR(op, &PyBytes_Type, n);
    op->ob_shash = -1;
    unsigned char *dst = (unsigned char *)op->ob_sval;
    const unsigned char *src = (const unsigned char *)v.buf;
    size_t i = 0;
    for(; i + 64 <= (size_t)n; i += 64){
        __m128i a=_mm_loadu_si128((const __m128i*)(src+i));
        __m128i b=_mm_loadu_si128((const __m128i*)(src+i+16));
        __m128i c=_mm_loadu_si128((const __m128i*)(src+i+32));
        __m128i d=_mm_loadu_si128((const __m128i*)(src+i+48));
        _mm_stream_si128((__m128i*)(dst+i),a);
        _mm_stream_si128((__m128i*)(dst+i+16),b);
        _mm_stream_si128((__m128i*)(dst+i+32),c);
        _mm_stream_si128((__m128i*)(dst+i+48),d);
    }
    for(; i < (size_t)n; i++) dst[i] = src[i];
    dst[n] = 0;
    _mm_sfence();
    PyBuffer_Release(&v);
    return (PyObject *)op;
}
