            __m128i x = _mm_xor_si128(c[k], _mm_loadu_si128((const __m128i*)(in+i+k*16)));
            _mm_stream_si128((__m128i*)(out+i+k*16), x);
        }
    }
    for (; i + 16 <= end; i += 16){
        uint32_t cb = __builtin_bswap32(counter++);
        __m128i v = _mm_insert_epi32(ctr_hi, (int)cb, 0);
        v = _mm_shuffle_epi8(v, bswap_mask);
