        __m128i v = _mm_insert_epi32(ctr_hi, (int)cb, 0);
        v = _mm_shuffle_epi8(v, bswap_mask);
        v = _mm_xor_si128(v, rk[0]);
        for (int rnd=1; rnd<nr; rnd++) v = _mm_aesenc_si128(v, rk[rnd]);
