static void *thread_main(void *arg){
    long id = (long)arg;
    pthread_mutex_lock(&mtx[id]);
    for(;;){
        while(jobflag[id]==0) pthread_cond_wait(&cv[id], &mtx[id]);
        if(jobflag[id]<0){ pthread_mutex_unlock(&mtx[id]); return NULL; }
        pthread_mutex_unlock(&mtx[id]);
        aes_ctr_chunk(&jobs[id]);
        pthread_mutex_lock(&mtx[id]);
        jobflag[id]=0; doneflag[id]=1; pthread_cond_signal(&done_cv[id]);
    }
}

static void ensure_threads(void){
    if(started) return;
    for(int t=0;t<NTHREADS;t++){
        pthread_mutex_init(&mtx[t], NULL);
        pthread_cond_init(&cv[t], NULL);
        pthread_cond_init(&done_cv[t], NULL);
        jobflag[t]=0; doneflag[t]=0;
        pthread_create(&threads[t], NULL, thread_main, (void*)(long)t);
