static PyObject *aes_ctr(PyObject *self, PyObject *args){
    Py_buffer key, nonce, pt;
    if(!PyArg_ParseTuple(args,"y*y*y*",&key,&nonce,&pt)) return NULL;
    if(nonce.len!=12){ PyBuffer_Release(&key);PyBuffer_Release(&nonce);PyBuffer_Release(&pt);
