    if(nr<0){ PyBuffer_Release(&key);PyBuffer_Release(&nonce);PyBuffer_Release(&pt);
        PyErr_SetString(PyExc_ValueError,"bad key length"); return NULL; }
    Py_ssize_t n = pt.len;
    PyBytesObject *op = (PyBytesObject *)PyObject_Malloc(sizeof(PyBytesObject)+n);
    if(!op){ PyBuffer_Release(&key);PyBuffer_Release(&nonce);PyBuffer_Release(&pt); return PyErr_NoMemory(); }
    PyObject_INIT_VAR(op, &PyBytes_Type, n);
    op->ob_shash = -1;
