    out[n]=0;

    unsigned char ctr0[16];
    memcpy(ctr0, nonce.buf, 12);
    ctr0[12]=0; ctr0[13]=0; ctr0[14]=0; ctr0[15]=2; /* first data counter */

    ensure_threads();
