        jobs[t].nr = nr; memcpy(jobs[t].ctr0, ctr0, 16);
        for(int k=0;k<=nr;k++) jobs[t].rk[k]=rk[k];
        pos += len;
    }
    for(int t=0;t<T;t++){ pthread_mutex_lock(&mtx[t]); doneflag[t]=0; jobflag[t]=1; pthread_cond_signal(&cv[t]); pthread_mutex_unlock(&mtx[t]); }
    for(int t=0;t<T;t++){ pthread_mutex_lock(&mtx[t]); while(!doneflag[t]) pthread_cond_wait(&done_cv[t], &mtx[t]); pthread_mutex_unlock(&mtx[t]); }

